{-| @Backend.Runtime.Host.Handle — open files behind their tokens, as `Pudu.Eval.Handle` answers them. -}
module Pudu.Backend.Runtime.Host.Handle (hostHandleParts) where

import Data.Text (Text)

{-| Each part: its name, the parts it needs, and its lines. -}
hostHandleParts :: [(Text, [Text], [Text])]
hostHandleParts =
  [ ("host_handles", ["host_optional", "host_files", "host_fail", "kernel_signed"],
      [ "/* Open files behind their tokens, numbered from one in their own run. */"
      , "typedef struct { FILE *stream; int writer; } pudu_host_handle;"
      , "PUDU_OPTIONAL static pudu_host_handle *pudu_host_handle_table = NULL;"
      , "PUDU_OPTIONAL static size_t pudu_host_handle_room = 0, pudu_host_handle_held = 0;"
      , "PUDU_OPTIONAL static int64_t pudu_host_handle_next = 1;"
      , "PUDU_OPTIONAL static inline pudu_host_handle *pudu_host_handle_find(pudu_int token) {"
      , "  int64_t wanted = pudu_kernel_signed(token.bits);"
      , "  if (wanted < 1 || (uint64_t)wanted >= pudu_host_handle_room || pudu_host_handle_table[wanted].stream == NULL) return NULL;"
      , "  return &pudu_host_handle_table[wanted];"
      , "}"
      ])
  , ("host_open_handle", ["host_handles", "host_done", "host_grow", "kernel_int"],
      [ "/* Mode 0 reads, 1 writes over, 2 writes after. */"
      , "static pudu_int pudu_host_open_handle(pudu_text path, int mode) {"
      , "  char *name = pudu_host_path(path);"
      , "  int descriptor = open(name, mode == 0 ? O_RDONLY : O_WRONLY | O_CREAT | (mode == 1 ? O_TRUNC : O_APPEND), 0666);"
      , "  int code = errno;"
      , "  struct stat found;"
      , "  FILE *stream;"
      , "  int64_t token;"
      , "  free(name);"
      , "  if (descriptor < 0) { pudu_host_fail_io(path, \"openFile\", code); return pudu_kernel_int(0); }"
      , "  if (fstat(descriptor, &found) == 0 && S_ISDIR(found.st_mode)) {"
      , "    (void)close(descriptor);"
      , "    pudu_host_fail_reason(path, \"openFile\", \"inappropriate type\", \"is a directory\");"
      , "    return pudu_kernel_int(0);"
      , "  }"
      , "  stream = fdopen(descriptor, mode == 0 ? \"rb\" : mode == 1 ? \"wb\" : \"ab\");"
      , "  if (stream == NULL) { code = errno; (void)close(descriptor); pudu_host_fail_io(path, \"openFile\", code); return pudu_kernel_int(0); }"
      , "  token = pudu_host_handle_next++;"
      , "  if ((size_t)token >= pudu_host_handle_room) {"
      , "    size_t room = pudu_host_handle_room < 8 ? 8 : pudu_host_handle_room * 2;"
      , "    pudu_host_handle *table;"
      , "    while (room <= (size_t)token) room *= 2;"
      , "    table = pudu_host_grow(pudu_host_handle_table, room * sizeof *table);"
      , "    memset(table + pudu_host_handle_room, 0, (room - pudu_host_handle_room) * sizeof *table);"
      , "    pudu_host_handle_table = table;"
      , "    pudu_host_handle_room = room;"
      , "  }"
      , "  pudu_host_handle_table[token].stream = stream;"
      , "  pudu_host_handle_table[token].writer = mode != 0;"
      , "  pudu_host_handle_held += 1;"
      , "  pudu_host_done(0);"
      , "  return pudu_kernel_int(token);"
      , "}"
      ])
  , ("host_read_chunk", ["host_handles", "host_done", "kernel_fresh", "bytes_wrap"],
      [ "/* Up to count bytes; state 2 at the end of the file. */"
      , "static pudu_box *pudu_host_read_chunk(pudu_int token, pudu_int count) {"
      , "  int64_t wanted = pudu_kernel_signed(count.bits);"
      , "  pudu_host_handle *handle;"
      , "  unsigned char *bytes;"
      , "  pudu_text chunk;"
      , "  size_t got;"
      , "  if (wanted <= 0) { pudu_host_done(0); return pudu_bytes_wrap(pudu_kernel_fresh(0, &bytes)); }"
      , "  handle = pudu_host_handle_find(token);"
      , "  if (handle == NULL) { pudu_host_fail(\"the handle is closed\"); return NULL; }"
      , "  if (handle->writer) { pudu_host_fail(\"the handle was opened for writing\"); return NULL; }"
      , "  chunk = pudu_kernel_fresh((size_t)wanted, &bytes);"
      , "  got = fread(bytes, 1, (size_t)wanted, handle->stream);"
      , "  if (got == 0) {"
      , "    int failed = ferror(handle->stream), code = errno;"
      , "    pudu_text none = {(const unsigned char *)\"\", 0, NULL};"
      , "    pudu_text_release(chunk);"
      , "    if (failed) { clearerr(handle->stream); pudu_host_fail_io(none, \"hGetBuf\", code); return NULL; }"
      , "    pudu_host_done(2);"
      , "    return NULL;"
      , "  }"
      , "  chunk.length = got;"
      , "  pudu_host_done(0);"
      , "  return pudu_bytes_wrap(chunk);"
      , "}"
      ])
  , ("host_write_chunk", ["host_handles", "host_done"],
      [ "static int pudu_host_write_chunk(pudu_int token, pudu_box *chunk) {"
      , "  pudu_host_handle *handle = pudu_host_handle_find(token);"
      , "  pudu_text bytes = chunk->fields[0].text, none = {(const unsigned char *)\"\", 0, NULL};"
      , "  if (handle == NULL) { pudu_host_fail(\"the handle is closed\"); return 0; }"
      , "  if (!handle->writer) { pudu_host_fail(\"the handle was opened for reading\"); return 0; }"
      , "  if (bytes.length != 0 && fwrite(bytes.bytes, 1, bytes.length, handle->stream) != bytes.length) {"
      , "    int code = errno;"
      , "    clearerr(handle->stream);"
      , "    pudu_host_fail_io(none, \"hPutBuf\", code);"
      , "    return 0;"
      , "  }"
      , "  pudu_host_done(0);"
      , "  return 1;"
      , "}"
      ])
  , ("host_flush_writer", ["host_handles", "host_done"],
      [ "static int pudu_host_flush_writer(pudu_int token) {"
      , "  pudu_host_handle *handle = pudu_host_handle_find(token);"
      , "  pudu_text none = {(const unsigned char *)\"\", 0, NULL};"
      , "  if (handle == NULL) { pudu_host_fail(\"the handle is closed\"); return 0; }"
      , "  if (handle->writer && fflush(handle->stream) != 0) { int code = errno; clearerr(handle->stream); pudu_host_fail_io(none, \"hFlush\", code); return 0; }"
      , "  pudu_host_done(0);"
      , "  return 1;"
      , "}"
      ])
  , ("host_close_handle", ["host_handles", "host_done"],
      [ "/* Closing a handle that is not open is done already. */"
      , "static int pudu_host_close_handle(pudu_int token) {"
      , "  pudu_host_handle *handle = pudu_host_handle_find(token);"
      , "  pudu_text none = {(const unsigned char *)\"\", 0, NULL};"
      , "  int failed, code;"
      , "  if (handle == NULL) { pudu_host_done(0); return 1; }"
      , "  failed = fclose(handle->stream);"
      , "  code = errno;"
      , "  handle->stream = NULL;"
      , "  pudu_host_handle_held -= 1;"
      , "  if (pudu_host_handle_held == 0) { free(pudu_host_handle_table); pudu_host_handle_table = NULL; pudu_host_handle_room = 0; }"
      , "  if (failed != 0) { pudu_host_fail_io(none, \"hClose\", code); return 0; }"
      , "  pudu_host_done(0);"
      , "  return 1;"
      , "}"
      ])
  ]
